style.css:
body {

/* Set the background image /

background-image: url('https://i.postimg.cc/Dwm3RGdg/2.jpg');

background-size: cover; / Cover the entire viewport /

background-position: center; / Center the image /

background-repeat: no-repeat; / Prevent repeating the image /

height: 100vh; / Full height of the viewport /

color: red; / Red text color /

font-family: Arial, sans-serif; / Basic font family /

display: flex; / Use flexbox for centering /

justify-content: center; / Center content horizontally /

align-items: center; / Center content vertically /

text-align: center; / Center text /

margin: 0; / Remove default margin */

}h1 {

font-size: 3em; /* Large headline /

text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5); / Soft shadow for readability */

}p {

font-size: 1.5em; /* Medium paragraph text /

  max-width: 600px; / Limit width of paragraph */}
